const leads = ($('Get leads').first().json.data || []).filter(l => !l.is_archived);
const deals = $('Get deals').first().json.data || [];
const stages = {}; for (const s of ($('Get stages').first().json.data || [])) stages[s.id] = s.pipeline_name + ' / ' + s.name;
const now = DateTime.now().setZone('America/Winnipeg');
const weekAgo = now.minus({ days: 7 });
const t = s => s ? DateTime.fromISO(String(s).replace(' ', 'T'), { zone: 'utc' }).setZone('America/Winnipeg') : null;
const esc = s => String(s || '').replace(/[<>&]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c]));
const ago = d => { const n = Math.floor(now.diff(d, 'days').days); return n === 0 ? 'today' : n + 'd ago'; };
const money = v => v ? '$' + Number(v).toLocaleString('en-CA') : '';
const real = x => !/zztest/i.test(x.title || '');
const newLeads = leads.filter(real).filter(l => t(l.add_time) >= weekAgo);
const noNext = leads.filter(real).filter(l => !l.next_activity_id && t(l.add_time) <= now.minus({ hours: 24 }));
const open = deals.filter(real).filter(d => d.status === 'open');
const rotting = open.filter(d => d.rotten_time);
const proposals = open.filter(d => [4, 8].includes(d.stage_id));
const won = deals.filter(real).filter(d => d.status === 'won' && t(d.won_time) >= weekAgo);
const lost = deals.filter(real).filter(d => d.status === 'lost' && t(d.lost_time) >= weekAgo);
const list = (title, rows, fmt) => '<h3 style="margin:18px 0 6px">' + title + ' (' + rows.length + ')</h3>' + (rows.length ? '<ul style="margin:0;padding-left:18px">' + rows.slice(0, 25).map(r => '<li>' + fmt(r) + '</li>').join('') + '</ul>' + (rows.length > 25 ? '<p>…and ' + (rows.length - 25) + ' more</p>' : '') : '<p style="color:#777;margin:0">None</p>');
const html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">'
  + '<p>Pipeline for the week of ' + now.toFormat('d LLL yyyy') + '. Open deals: ' + open.length + ', worth ' + money(open.reduce((a, d) => a + (Number(d.value) || 0), 0)) + '.</p>'
  + list('Leads with no next step after 24 hours', noNext, l => esc(l.title) + ' · added ' + ago(t(l.add_time)))
  + list('Rotting deals', rotting, d => esc(d.title) + ' · ' + esc(stages[d.stage_id] || '') + ' · stuck since ' + ago(t(d.rotten_time)))
  + list('Proposals and quotes waiting on an answer', proposals, d => esc(d.title) + ' · ' + money(d.value) + ' · sent ' + ago(t(d.stage_change_time || d.add_time)))
  + list('New leads this week', newLeads, l => esc(l.title))
  + list('Won this week', won, d => esc(d.title) + ' · ' + money(d.value))
  + list('Lost this week', lost, d => esc(d.title) + (d.lost_reason ? ' · ' + esc(d.lost_reason) : ''))
  + '<p style="color:#777;margin-top:18px">Sent automatically every Monday at 7:00 from n8n.</p></div>';
return [{ json: { subject: 'Pipeline this week: ' + noNext.length + ' leads need a next step, ' + rotting.length + ' rotting deals', html } }];

